    "sd.excludeRange" to row("Bereich aussortieren", "Bereich aussortieren", "Bereich aussortieren", "Exclude range", "Exclude range", "Exclude range", "Exclude range"),
    "sd.excludeRangeConfirm" to row("Zeitbereich {from}–{to} aus der Auswertung nehmen? Die Aufnahme bleibt gespeichert, umkehrbar.", "Zeitbereich {from}–{to} aus der Auswertung nehmen? Die Aufnahme bleibt gespeichert, umkehrbar.", "Zeitbereich {from}–{to} aus der Auswertung nehmen? Die Aufnahme bleibt gespeichert, umkehrbar.", "Exclude {from}–{to} from the analysis? The recording is kept, this is reversible.", "Exclude {from}–{to} from the analysis? The recording is kept, this is reversible.", "Exclude {from}–{to} from the analysis? The recording is kept, this is reversible.", "Exclude {from}–{to} from the analysis? The recording is kept, this is reversible."),
    "sd.excludeRangeHint" to row("Liegt der Störteil mitten in der Aufnahme (z. B. Autofahrt zwischen zwei Spots), kannst du den gewählten Bereich stattdessen aussortieren — der Rest davor und danach bleibt in der Auswertung.", "Liegt der Störteil mitten in der Aufnahme (z. B. Autofahrt zwischen zwei Spots), kannst du den gewählten Bereich stattdessen aussortieren — der Rest davor und danach bleibt in der Auswertung.", "Liegt der Störteil mitten in der Aufnahme (z. B. Autofahrt zwischen zwei Spots), kannst du den gewählten Bereich stattdessen aussortieren — der Rest davor und danach bleibt in der Auswertung.", "If the part to remove sits in the middle of the recording (e.g. driving between two spots), exclude the selected range instead — everything before and after stays in the analysis.", "If the part to remove sits in the middle of the recording (e.g. driving between two spots), exclude the selected range instead — everything before and after stays in the analysis.", "If the part to remove sits in the middle of the recording (e.g. driving between two spots), exclude the selected range instead — everything before and after stays in the analysis.", "If the part to remove sits in the middle of the recording (e.g. driving between two spots), exclude the selected range instead — everything before and after stays in the analysis."),
    "sd.excludeRun" to row("Lauf aussortieren", "Lauf aussortieren", "Lauf aussortieren", "Drop run", "Drop run", "Drop run", "Drop run"),
    "sd.excludeConfirm" to row("Diesen Lauf aus der Auswertung nehmen?\n\nEr zählt dann nicht mehr bei Läufen, Foil-Zeit, Distanz, Pumps und Rekorden. Die Aufnahme selbst bleibt vollständig gespeichert — du kannst den Lauf jederzeit wieder aufnehmen.", "Diesen Lauf aus der Auswertung nehmen?\n\nEr zählt dann nicht mehr bei Läufen, Foil-Zeit, Distanz, Pumps und Rekorden. Die Aufnahme selbst bleibt vollständig gespeichert — du kannst den Lauf jederzeit wieder aufnehmen.", "Diesen Lauf aus der Auswertung nehmen?\n\nEr zählt dann nicht mehr bei Läufen, Foil-Zeit, Distanz, Pumps und Rekorden. Die Aufnahme selbst bleibt vollständig gespeichert — du kannst den Lauf jederzeit wieder aufnehmen.", "Drop this run from the evaluation?\n\nIt will no longer count towards runs, foiling time, distance, pumps and records. The recording itself stays fully stored — you can bring the run back at any time.", "Drop this run from the evaluation?\n\nIt will no longer count towards runs, foiling time, distance, pumps and records. The recording itself stays fully stored — you can bring the run back at any time.", "Drop this run from the evaluation?\n\nIt will no longer count towards runs, foiling time, distance, pumps and records. The recording itself stays fully stored — you can bring the run back at any time.", "Drop this run from the evaluation?\n\nIt will no longer count towards runs, foiling time, distance, pumps and records. The recording itself stays fully stored — you can bring the run back at any time."),
    "sd.excludedTitle" to row("{n} Läufe aussortiert", "{n} Läufe aussortiert", "{n} Läufe aussortiert", "{n} runs dropped", "{n} runs dropped", "{n} runs dropped", "{n} runs dropped"),
    "sd.excludedTitleOne" to row("1 Lauf aussortiert", "1 Lauf aussortiert", "1 Lauf aussortiert", "1 run dropped", "1 run dropped", "1 run dropped", "1 run dropped"),
    "sd.excludedHint" to row("Diese Zeitabschnitte zählen nicht in die Auswertung (Läufe, Foil-Zeit, Distanz, Pumps, Rekorde). Die Aufnahme bleibt vollständig gespeichert — jederzeit umkehrbar.", "Diese Zeitabschnitte zählen nicht in die Auswertung (Läufe, Foil-Zeit, Distanz, Pumps, Rekorde). Die Aufnahme bleibt vollständig gespeichert — jederzeit umkehrbar.", "Diese Zeitabschnitte zählen nicht in die Auswertung (Läufe, Foil-Zeit, Distanz, Pumps, Rekorde). Die Aufnahme bleibt vollständig gespeichert — jederzeit umkehrbar.", "These time ranges do not count towards the evaluation (runs, foiling time, distance, pumps, records). The recording stays fully stored — reversible at any time.", "These time ranges do not count towards the evaluation (runs, foiling time, distance, pumps, records). The recording stays fully stored — reversible at any time.", "These time ranges do not count towards the evaluation (runs, foiling time, distance, pumps, records). The recording stays fully stored — reversible at any time.", "These time ranges do not count towards the evaluation (runs, foiling time, distance, pumps, records). The recording stays fully stored — reversible at any time."),
